func TestTombstoneTrimProtected(t *testing.T) {
	build := func() []Op {
		e := New()
		mustPut(t, e, "k", "v1") // 1
		e.DeleteRange("a", "z")  // 2
		mustPut(t, e, "k", "v3") // 3
		e.DeleteRange("a", "m")  // 4 older
		mustPut(t, e, "k", "v5") // 5
		e.DeleteRange("a", "k")  // 6 newer, dominates 4 on [a,k)
		mustPut(t, e, "k", "v7") // 7
		return e.Ops()
	}
	ops := build()

	out := Compact(ops, []uint64{3, 5, 7})
	for _, snap := range []uint64{3, 5, 7} {
		got := Replay(out, snap)
		want := Replay(ops, snap)
		if len(got) != len(want) {
			t.Fatalf("snap %d size mismatch got=%v want=%v", snap, got, want)
		}
		for k, v := range want {
			if !bytes.Equal(got[k], v) {
				t.Fatalf("snap %d key %q got=%q want=%q", snap, k, got[k], v)
			}
		}
	}
	kept := false
	for _, o := range out {
		if o.Kind == DeleteRange && o.Seq == 4 && o.Key == "a" && o.End == "m" {
			kept = true
		}
	}
	if !kept {
		t.Fatalf("tombstone 4 was trimmed although snapshot 5 protects it")
	}

	out2 := Compact(ops, []uint64{3, 7})
	n4 := 0
	for _, o := range out2 {
		if o.Kind == DeleteRange && o.Seq == 4 {
			n4++
			if o.Key != "k" || o.End != "m" {
				t.Fatalf("expected trimmed tombstone [k,m), got [%s,%s)", o.Key, o.End)
			}
		}
	}
	if n4 != 1 {
		t.Fatalf("expected one fragment of tombstone 4, got %d", n4)
	}
	for _, snap := range []uint64{3, 7} {
		got := Replay(out2, snap)
		want := Replay(ops, snap)
		if len(got) != len(want) {
			t.Fatalf("snap %d size mismatch got=%v want=%v", snap, got, want)
		}
		for k, v := range want {
			if !bytes.Equal(got[k], v) {
				t.Fatalf("snap %d key %q got=%q want=%q", snap, k, got[k], v)
			}
		}
	}
}

func TestRandomizedCompactionDifferential(t *testing.T) {
	keys := []string{"a", "b", "c", "d", "e"}
	for seed := int64(0); seed < 200; seed++ {
		r := rand.New(rand.NewSource(seed))
		e := New()
		var protected []uint64
		n := 60 + r.Intn(60)
		for i := 0; i < n; i++ {
			switch r.Intn(10) {
			case 0, 1, 2, 3:
				k := keys[r.Intn(len(keys))]
				e.Put(k, []byte(fmt.Sprintf("v%d_%d", seed, i)))
			case 4, 5:
				k := keys[r.Intn(len(keys))]
				e.Delete(k)
			default:
				i0 := r.Intn(len(keys))
				i1 := r.Intn(len(keys))
				if i0 > i1 {
					i0, i1 = i1, i0
				}
				start, end := keys[i0], keys[i1]
				if start == end {
					end = string(start[0] + 1)
				}
				e.DeleteRange(start, end)
			}
			if r.Intn(4) == 0 {
				protected = append(protected, e.Seq())
			}
		}
		original := e.Ops()

		for _, p := range protected {
			checkSnapshot(t, e, original, p)
		}
		checkSnapshot(t, e, original, e.Seq())

		prot := append([]uint64(nil), protected...)
		prot = append(prot, e.Seq())
		compacted := Compact(original, prot)
		ce := NewFromOps(compacted)
		for _, p := range prot {
			checkSnapshot(t, ce, original, p)
		}
		if len(compacted) > len(original) {
			t.Fatalf("seed %d: compaction grew %d -> %d", seed, len(original), len(compacted))
		}

		compacted2 := Compact(compacted, []uint64{e.Seq()})
		ce2 := NewFromOps(compacted2)
		checkSnapshot(t, ce2, original, e.Seq())
		for _, k := range keys {
			v1, ok1 := ce2.SnapshotAt(e.Seq()).Get(k)
			v2, ok2 := ce.SnapshotAt(e.Seq()).Get(k)
			if ok1 != ok2 || !bytes.Equal(v1, v2) {
				t.Fatalf("seed %d: second compaction diverged for %q", seed, k)
			}
		}
	}
}

func TestRandomTombstoneTrimFuzz(t *testing.T) {
	keys := []string{"a", "b", "c", "d", "e", "f"}
	for seed := int64(0); seed < 2000; seed++ {
		r := rand.New(rand.NewSource(seed))
		e := New()
		n := 5 + r.Intn(35)
		for i := 0; i < n; i++ {
			if r.Intn(2) == 0 {
				e.Put(keys[r.Intn(len(keys))], []byte(fmt.Sprintf("v%d", i)))
			} else {
				i0 := r.Intn(len(keys))
				i1 := r.Intn(len(keys))
				if i0 == i1 {
					i1 = (i0 + 1) % len(keys)
				}
				if i0 > i1 {
					i0, i1 = i1, i0
				}
				e.DeleteRange(keys[i0], keys[i1])
			}
		}
		max := e.Seq()
		var prot []uint64
		for s := uint64(1); s <= max; s++ {
			if r.Intn(3) == 0 {
				prot = append(prot, s)
			}
		}
		prot = append(prot, max)
		ops := e.Ops()
		out := Compact(ops, prot)
		for _, p := range prot {
			got := Replay(out, p)
			want := Replay(ops, p)
			if len(got) != len(want) {
				t.Fatalf("seed %d snap %d: size got=%d want=%d\nops=%v\nout=%v", seed, p, len(got), len(want), ops, out)
			}
			for k, v := range want {
				if !bytes.Equal(got[k], v) {
					t.Fatalf("seed %d snap %d key %q: got=%q want=%q\nops=%v\nout=%v", seed, p, k, got[k], v, ops, out)
				}
			}
		}
	}
}

func TestSnapshotsBeginEndDuringCompaction(t *testing.T) {
	e := New()
	e.Put("k", []byte("old")) // 1
	snapOld := e.Snapshot()   // seq 1
	e.DeleteRange("a", "z")   // 2
	e.Put("k", []byte("new")) // 3
	e.Delete("k")             // 4

	original := e.Ops()
	compacted := Compact(original, []uint64{snapOld.Seq(), e.Seq()})
	ce := NewFromOps(compacted)

	// Snapshot begins during compaction -> seq 4, sees deleted state.
	snapNew := ce.Snapshot()
	if _, ok := snapNew.Get("k"); ok {
		t.Fatalf("new snapshot should not see k")
	}
	// Snapshot ends during compaction -> pinned seq 1 result preserved.
	if v, ok := snapOld.Get("k"); !ok || string(v) != "old" {
		t.Fatalf("pinned snapshot lost: %q,%v", v, ok)
	}
	if v, ok := ce.SnapshotAt(1).Get("k"); !ok || string(v) != "old" {
		t.Fatalf("compacted engine lost pinned snapshot: %q,%v", v, ok)
	}
}

func TestWALTornRecordRecovery(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "wal")
	s, err := Open(path)
	if err != nil {
		t.Fatal(err)
	}
	s.Put("a", []byte("1"))
	s.Put("b", []byte("2"))
	s.Delete("a")
	s.Close()

	f, err := os.OpenFile(path, os.O_WRONLY|os.O_APPEND, 0o644)
	if err != nil {
		t.Fatal(err)
	}
	var hdr [8]byte
	binary.LittleEndian.PutUint32(hdr[0:4], 100) // huge length
	binary.LittleEndian.PutUint32(hdr[4:8], 0)
	f.Write(hdr[:])
	f.Write([]byte("partial"))
	f.Close()

	s2, err := Open(path)
	if err != nil {
		t.Fatal(err)
	}
	defer s2.Close()
	if _, ok := s2.Engine().SnapshotAt(3).Get("a"); ok {
		t.Fatalf("recovered engine should not see deleted a")
	}
	if v, ok := s2.Engine().SnapshotAt(2).Get("b"); !ok || string(v) != "2" {
		t.Fatalf("recovered engine lost b: %q,%v", v, ok)
	}
	if s2.Engine().Seq() != 3 {
		t.Fatalf("recovered seq = %d want 3", s2.Engine().Seq())
	}
}

func TestCrashSafeCompaction(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "wal")
	s, err := Open(path)
	if err != nil {
		t.Fatal(err)
	}
	s.Put("a", []byte("1")) // 1
	s.Put("b", []byte("2")) // 2
	s.Delete("a")           // 3
	s.Put("c", []byte("3")) // 4
	originalSeq := s.Engine().Seq()

	// Simulate a crash DURING compaction: temp written, rename never happened.
	compacted := Compact(s.Engine().Ops(), []uint64{originalSeq})
	if err := writeWAL(path+".tmp", compacted); err != nil {
		t.Fatal(err)
	}
	s.Close()

	s2, err := Open(path)
	if err != nil {
		t.Fatal(err)
	}
	if s2.Engine().Seq() != originalSeq {
		t.Fatalf("seq after crash = %d want %d", s2.Engine().Seq(), originalSeq)
	}
	if _, ok := s2.Engine().SnapshotAt(2).Get("a"); !ok {
		t.Fatalf("lost a at seq2 after crash")
	}
	if v, ok := s2.Engine().SnapshotAt(4).Get("c"); !ok || string(v) != "3" {
		t.Fatalf("lost c after crash: %q,%v", v, ok)
	}

	if err := s2.Compact([]uint64{originalSeq}); err != nil {
		t.Fatal(err)
	}
	s2.Close()
	s3, err := Open(path)
	if err != nil {
		t.Fatal(err)
	}
	defer s3.Close()
	want := Replay(compacted, originalSeq)
	got := Replay(s3.Engine().Ops(), s3.Engine().Seq())
	if len(got) != len(want) {
		t.Fatalf("after real compaction got %v want %v", got, want)
	}
	for k, v := range want {
		if !bytes.Equal(got[k], v) {
			t.Fatalf("after real compaction key %q got %q want %q", k, got[k], v)
		}
	}
}
